lines = ["; Erzeugt von make_installer_messages.py - NICHT von Hand aendern (die Tabelle steht im Skript; Platzhalter %1 %2, %n = Zeilenumbruch). Sechs Sprachen: english german french dutch italian spanish.", "[CustomMessages]"]
for key, vals in M.items():
    assert len(vals) == 6, key
    for lang, v in zip(LANGS, vals):
        lines.append(f"{lang}.{key}={v}")
data = "\r\n".join(lines) + "\r\n"
open(OUT, "wb").write(b"\xef\xbb\xbf" + data.encode("utf-8"))
print(len(M), "Meldungen,", len(lines), "Zeilen ->", OUT)
